'''
new='''        // Connect to the MCP server BEFORE handling the request
        console.log(`Connecting transport to MCP server...`);
        const server = createServer();

        // Clean up transport when closed. Hooked on the server rather than the
        // transport because connect() replaces transport.onclose.
        server.server.onclose = () => {
          const sid = transport.sessionId;
          if (sid && transports[sid]) {
            console.log(`Transport closed for session ${sid}, removing from transports map`);
            delete transports[sid];
          }
        };

        await server.connect(transport);
'''
assert old in s; s=s.replace(old,new); open(p,'w').write(s)
